NextBitsStream() {
        BitsStreamGenerator generator = new BitsStreamGenerator();
        int length = 1000;
        int bits[] = new int[length];
        long max = 0;
        for (int i = 0; i < length; i++) {
            bits[i] = generator.nextInt();
            max = FastMath.max(max, bits[i]);
        }
        assertThat(generator.nextInt(), is((int) max));
        assertThat(generator.nextInt(100), is((int) (max * 100)));
        assertThat(generator.nextInt(1000), is((int) (max * 1000)));
        assertThat(generator.nextInt(10000), is((int) (max * 10000)));
        assertThat(generator.nextInt(100000), is((int) (max * 100000)));
        assertThat(generator.nextInt(1000000), is((int) (max * 1000000)));
    }

